entries[238578] = { ["name"] = "Vantusrune: Das Grabmal des Sargeras", ["text"] = "Wirken in 2 sek.\nReagenzien:\nFahle Pigmente (8), Rosenrote Pigmente (30)\nVerringert die erforderlichen Materialien zur Herstellung einer Vantusrune: Das Grabmal des Sargeras.\nBeute von:\nKil'jaeden\nZone:\nDas Grabmal des Sargeras\n\nBenutzen: Stellt Euch auf die Energien des anvisierten Schlachtzugsbosses aus dem Grabmal des Sargeras ein, was Eure Vielseitigkeit um 3380 erhöht, während Ihr diesen Boss bekämpft. Dieser Effekt hält eine ganze Woche lang an.\n\nIhr könnt nur eine Vantusrune pro Woche nutzen.\n45" }
entries[238579] = { ["name"] = "Vantusrune: Das Grabmal des Sargeras", ["text"] = "Wirken in 2 sek.\nReagenzien:\nFahle Pigmente (6), Rosenrote Pigmente (30)\nVerringert erheblich die erforderlichen Materialien zur Herstellung einer Vantusrune: Das Grabmal des Sargeras.\nBeute von:\nDas Grabmal des Sargeras\n\nBenutzen: Stellt Euch auf die Energien des anvisierten Schlachtzugsbosses aus dem Grabmal des Sargeras ein, was Eure Vielseitigkeit um 3380 erhöht, während Ihr diesen Boss bekämpft. Dieser Effekt hält eine ganze Woche lang an.\n\nIhr könnt nur eine Vantusrune pro Woche nutzen.\n45" }
