entries[238656] = { ["name"] = "Schattenwelle", ["text"] = "Unbegrenzte Reichweite\nSofort\nEine Welle chaotischer Magie schlägt über Gegner vor dem Zaubernden hinweg und verursacht 8783 Schattenschaden. Außerdem hinterlässt sie Schattenpfützen im Bereich, die alle 1 Sek. 664 Schattenschaden verursachen." }
entries[238657] = { ["name"] = "Wildes Gebrüll", ["text"] = "20 Meter Reichweite\nWirken in 5 sek. 3 sek. Abklingzeit\nBrüllt laut, verursacht dadurch körperlichen Schaden und verwirrt Gegner für 3 Sek. Löst außerdem 'Wilder Geist' aus." }
