entries[238659] = { ["name"] = "Schwefelregen", ["text"] = "Unbegrenzte Reichweite\nSofort\nGoroth ruft mehrere Meteore herab, von denen jeder 142242 Feuerschaden verursacht, der gleichmäßig auf die jeweiligen Ziele verteilt wird. Eine Schwefelhöllenbestie erscheint, falls ein Meteor kein Ziel trifft." }
entries[238660] = { ["name"] = "Wilder Hieb", ["text"] = "Nahkampfreichweite\nWirken in 2 sek. 3 sek. Abklingzeit\nSchlägt nach Gegnern vor dem Zaubernden, fügt ihnen körperlichen Schaden zu und lässt sie 20 Sek. lang bluten." }
