entries[238673] = { ["name"] = "Doldendetonation", ["text"] = "Wirken in 0.5 sek.\nWenn der Peitscher in Nahkampfreichweite ist, explodiert er und fügt allen Gegnern in der Nähe 8754 Feuerschaden zu." }
