entries[238678] = { ["name"] = "Lautlose Lyrik", ["text"] = "100 Meter Reichweite\nWirken in 3 sek.\nDie Folianten öffnen sich und absorbieren auf magische Weise alle Geräusche in ihre uralten Seiten. Alle Spielercharaktere werden 5 Sek. lang zum Schweigen gebracht." }
